<p>सबमिट करने से सीट पक्की नहीं होती। अप्रूवल के बाद एडमिशन नंबर और लॉगिन जानकारी ईमेल पर मिलेगी।</p><button id="submitApplication" type="submit" disabled>फीस और चयन देखकर आवेदन जमा करें</button></form></div></main>
<script>
const campus=document.querySelector('#campus'),duration=document.querySelector('#duration'),plan=document.querySelector('#plan'),date=document.querySelector('#startDate'),timing=document.querySelector('#timing'),seats=document.querySelector('#seats'),status=document.querySelector('#availabilityStatus'),fees=document.querySelector('#fees'),submit=document.querySelector('#submitApplication');
const slots=[...duration.options].slice(1),plans=[...plan.options].slice(1);let windows=[],version=0,abort;
function clearAvailability(){windows=[];timing.replaceChildren(new Option('समय चुनें',''));timing.disabled=true;seats.replaceChildren();fees.hidden=true;submit.disabled=true;document.querySelector('#startTime').value='';document.querySelector('#endTime').value='';}
function filter(reset=false){
const oldDuration=reset?'':duration.value,oldPlan=reset?'':plan.value;
const campusSlots=slots.filter(o=>o.dataset.campus===campus.value);
duration.replaceChildren(new Option(!campus.value?'पहले कैंपस चुनें':campusSlots.length?'अवधि चुनें':'इस कैंपस में अवधि कॉन्फ़िगर नहीं है',''));
campusSlots.forEach(o=>duration.add(o.cloneNode(true)));duration.value=campusSlots.some(o=>o.value===oldDuration)?oldDuration:'';duration.disabled=!campusSlots.length;
const slotPlans=plans.filter(o=>o.dataset.campus===campus.value&&o.dataset.slot===duration.value);
plan.replaceChildren(new Option(!duration.value?'पहले अवधि चुनें':slotPlans.length?'फीस प्लान चुनें':'इस अवधि का फीस प्लान उपलब्ध नहीं है',''));
slotPlans.forEach(o=>plan.add(o.cloneNode(true)));plan.value=slotPlans.some(o=>o.value===oldPlan)?oldPlan:'';plan.disabled=!slotPlans.length;
load();}
async function load(){const current=++version;abort?.abort();clearAvailability();status.textContent='';if(!campus.value||!duration.value||!plan.value||!date.value)return;status.textContent='उपलब्ध समय और सीट जाँच रहे हैं…';abort=new AbortController();try{const url=new URL(@json(route('admission.availability')));url.search=new URLSearchParams({branch_id:campus.value,study_slot_id:duration.value,fee_plan_id:plan.value,start_date:date.value});const response=await fetch(url,{signal:abort.signal,headers:{Accept:'application/json'}});const data=await response.json();if(current!==version)return;if(!response.ok)throw new Error(data.message||'सीट की जानकारी नहीं मिली।');windows=data.times;windows.forEach((w,i)=>{const o=new Option(w.label+' · '+(w.available?w.available+' सीटें उपलब्ध':'सभी सीटें बुक'),String(i));o.disabled=!w.available;timing.add(o);});timing.disabled=!windows.some(w=>w.available);status.textContent=timing.disabled?'इस अवधि में कोई सीट उपलब्ध नहीं है। दूसरी अवधि या कैंपस चुनें।':'अब समय चुनें।';fees.textContent='मासिक फीस ₹'+data.monthly_fee+' · प्रवेश शुल्क ₹'+data.admission_fee+' · रजिस्ट्रेशन ₹'+data.registration_fee+' · सिक्योरिटी ₹'+data.security_deposit+' · कुल शुरुआती शुल्क ₹'+(Number(data.monthly_fee)+Number(data.admission_fee)+Number(data.registration_fee)+Number(data.security_deposit)).toFixed(2)+' · सदस्यता '+date.value+' से '+data.expiry+' तक। लॉकर का शुल्क अलग है, यदि चुना गया।';}catch(error){if(error.name!=='AbortError'&&current===version){status.textContent=error.message;}}}
campus.addEventListener('change',()=>filter(true));duration.addEventListener('change',()=>{plan.value='';filter();});plan.addEventListener('change',load);date.addEventListener('change',load);
timing.addEventListener('change',()=>{seats.replaceChildren();submit.disabled=true;fees.hidden=true;const w=windows[Number(timing.value)];if(timing.value===''||!w)return;document.querySelector('#startTime').value=w.start||'';document.querySelector('#endTime').value=w.end||'';w.seats.forEach(s=>{const label=document.createElement('label'),radio=document.createElement('input');radio.type='radio';radio.name='preferred_seat_id';radio.value=s.id;radio.required=true;radio.addEventListener('change',()=>{submit.disabled=false;fees.hidden=false;status.textContent='समय: '+w.label+' · सीट: '+s.number+' · '+s.hall;});label.append(radio,document.createTextNode('सीट '+s.number+' · '+s.hall));seats.append(label);});status.textContent='इस समय में अपनी सीट चुनें।';});filter();
</script></body></html>